    patterns = {}
    for r in range(h):
        for c in range(width + 1, w0):
            v = grid[r][c]
            if v != 0 and v != bg:
                patterns.setdefault(v, set()).add((r, c))
    normalized = {}
    for color, cells in patterns.items():
        r0 = min(r for r, c in cells); c0 = min(c for r, c in cells)
        normalized[color] = (max(r for r, c in cells)-r0+1,
